node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const customerId = 'user_d3d5d0c8';
const cartId = 'CART-' + customerId;

// 1. Remove Harbor Cotton Crew Tee (CI-0023) from cart
db.prepare('DELETE FROM cart_items WHERE cart_item_id = ?').run('CI-0023');

// 2. Update cart item_ids to remove CI-0023
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const itemIds = JSON.parse(cart.item_ids_json).filter(id => id !== 'CI-0023');

// 3. Recalculate cart totals with only the Wireless Ergonomic Mouse
// Mouse price = \$39, standard shipping = \$6
const subtotal = 39;
const shippingCost = cart.shipping_cost;  // keep standard shipping at \$6
const total = subtotal + shippingCost;

db.prepare('UPDATE carts SET item_ids_json = ?, subtotal = ?, total = ? WHERE cart_id = ?')
  .run(JSON.stringify(itemIds), subtotal, total, cartId);

// 4. Deduct store credit (\$39) from user's balance (\$66 -> \$27)
const mousePrice = 39;
db.prepare('UPDATE users SET store_credit_balance = store_credit_balance - ? WHERE user_id = ?')
  .run(mousePrice, customerId);

// 5. Verify final state
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const updatedItems = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all(cartId);
const updatedUser = db.prepare('SELECT name, store_credit_balance, loyalty_points FROM users WHERE user_id = ?').get(customerId);

console.log('=== UPDATED CART ===');
console.log(JSON.stringify(updatedCart, null, 2));
console.log('\n=== CART ITEMS ===');
console.log(JSON.stringify(updatedItems, null, 2));
console.log('\n=== CUSTOMER ACCOUNT ===');
console.log(JSON.stringify(updatedUser, null, 2));

db.close();
"
